  "inlineSchema": "// ============================================================\n// FimoStay — schema.prisma (MVP)\n// Database: Supabase Postgres\n// Catatan: AdminProfile.id harus sama dengan id di auth.users\n// (Supabase Auth) — dibuat lewat trigger/hook saat admin dibuat,\n// bukan dikelola Prisma langsung karena auth.users di schema lain.\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\") // connection pooler (pgbouncer), dipakai runtime\n  directUrl = env(\"DIRECT_URL\") // direct connection, dipakai untuk migration\n}\n\n// ------------------------------------------------------------\n// ENUMS\n// ------------------------------------------------------------\n\nenum AdminRole {\n  SUPERADMIN\n  STAFF\n}\n\nenum KosStatus {\n  ACTIVE // tampil di publik\n  HIDDEN_STALE // disembunyikan otomatis (belum update > 7 hari)\n  HIDDEN_MANUAL // disembunyikan manual oleh tim (mis. kamar penuh permanen)\n}\n\nenum TransactionType {\n  SELF_SEARCH // Rp30rb — buka kontak 1 kos\n  RECOMMENDATION // Rp150rb — 5 rekomendasi kos\n}\n\nenum TransactionStatus {\n  PENDING\n  VERIFIED\n  REJECTED\n}\n\n// ------------------------------------------------------------\n// ADMIN / TIM\n// ------------------------------------------------------------\n\nmodel AdminProfile {\n  id        String    @id // sama dengan auth.users.id di Supabase Auth\n  fullName  String\n  email     String    @unique @db.VarChar(255)\n  role      AdminRole @default(STAFF)\n  createdAt DateTime  @default(now())\n\n  updatedKos           Kos[]         @relation(\"KosUpdatedBy\")\n  verifiedTransactions Transaction[] @relation(\"TransactionVerifiedBy\")\n  auditLogs            AuditLog[]\n\n  @@map(\"admin_profiles\")\n}\n\n// ------------------------------------------------------------\n// OWNER & KOS\n// ------------------------------------------------------------\n\nmodel Owner {\n  id        String   @id @default(uuid())\n  name      String\n  phone     String\n  address   String?\n  notes     String? // catatan internal tim, tidak tampil ke publik\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  kos Kos[]\n\n  @@map(\"owners\")\n}\n\nmodel Kos {\n  id           String    @id @default(uuid())\n  slug         String    @unique\n  name         String\n  description  String?\n  address      String\n  city         String\n  latitude     Float?\n  longitude    Float?\n  priceMonthly Int // dalam rupiah\n  roomType     String? // \"putra\" | \"putri\" | \"campur\"\n  facilities   String[]  @default([])\n  status       KosStatus @default(ACTIVE)\n\n  ownerId String\n  owner   Owner  @relation(fields: [ownerId], references: [id])\n\n  media KosMedia[]\n\n  lastUpdatedAt DateTime      @default(now()) // dipakai cron auto-hide 7 hari\n  updatedById   String?\n  updatedBy     AdminProfile? @relation(\"KosUpdatedBy\", fields: [updatedById], references: [id])\n\n  selfSearchTransactions Transaction[]        @relation(\"TransactionTargetKos\")\n  recommendationItems    RecommendationItem[]\n  auditLogs              AuditLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([city])\n  @@index([lastUpdatedAt])\n  @@map(\"kos\")\n}\n\nmodel KosMedia {\n  id        String   @id @default(uuid())\n  kosId     String\n  kos       Kos      @relation(fields: [kosId], references: [id], onDelete: Cascade)\n  url       String // path/object key di Cloudflare R2\n  isCover   Boolean  @default(false)\n  order     Int      @default(0)\n  createdAt DateTime @default(now())\n\n  @@index([kosId])\n  @@map(\"kos_media\")\n}\n\n// ------------------------------------------------------------\n// PENCARI KOS\n// ------------------------------------------------------------\n\nmodel Searcher {\n  id        String   @id @default(uuid())\n  phone     String\n  name      String?\n  createdAt DateTime @default(now())\n\n  transactions Transaction[]\n\n  @@index([phone])\n  @@map(\"searchers\")\n}\n\n// ------------------------------------------------------------\n// TRANSAKSI (pembayaran manual)\n// ------------------------------------------------------------\n\nmodel Transaction {\n  id     String            @id @default(uuid())\n  type   TransactionType\n  amount Int // 30000 atau 150000\n  status TransactionStatus @default(PENDING)\n\n  proofUrl String? // bukti transfer, path di R2\n\n  searcherId String\n  searcher   Searcher @relation(fields: [searcherId], references: [id])\n\n  // dipakai kalau type = SELF_SEARCH (kos yang mau dibuka kontaknya)\n  targetKosId String?\n  targetKos   Kos?    @relation(\"TransactionTargetKos\", fields: [targetKosId], references: [id])\n\n  // dipakai kalau type = RECOMMENDATION\n  preferenceNotes     String? // budget, lokasi, tipe kamar, dst (bebas teks/JSON)\n  recommendationToken String? @unique // dipakai di URL /rekomendasi/[token]\n\n  verifiedById String?\n  verifiedBy   AdminProfile? @relation(\"TransactionVerifiedBy\", fields: [verifiedById], references: [id])\n  verifiedAt   DateTime?\n\n  createdAt DateTime @default(now())\n\n  recommendationItems RecommendationItem[]\n  auditLogs           AuditLog[]\n\n  @@index([status])\n  @@index([type])\n  @@map(\"transactions\")\n}\n\nmodel RecommendationItem {\n  id            String      @id @default(uuid())\n  transactionId String\n  transaction   Transaction @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n  kosId         String\n  kos           Kos         @relation(fields: [kosId], references: [id])\n  order         Int         @default(0)\n  createdAt     DateTime    @default(now())\n\n  @@unique([transactionId, kosId])\n  @@map(\"recommendation_items\")\n}\n\n// ------------------------------------------------------------\n// AUDIT LOG\n// ------------------------------------------------------------\n\nmodel AuditLog {\n  id         String @id @default(uuid())\n  entityType String // \"kos\" | \"owner\" | \"transaction\"\n  entityId   String\n  action     String // \"create\" | \"update\" | \"hide\" | \"verify\" | \"reject\"\n  changes    Json? // simpan diff sebelum/sesudah kalau perlu\n\n  kosId String?\n  kos   Kos?    @relation(fields: [kosId], references: [id])\n\n  transactionId String?\n  transaction   Transaction? @relation(fields: [transactionId], references: [id])\n\n  adminId String?\n  admin   AdminProfile? @relation(fields: [adminId], references: [id])\n\n  createdAt DateTime @default(now())\n\n  @@index([entityType, entityId])\n  @@map(\"audit_logs\")\n}\n",
